mod io;
use quantum_ecc::circuit::{Op,OperationType as K};
use sha3::{Digest,Sha3_256};
const NO:u64=u64::MAX;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]enum V{Z,O,C,Q}
fn and(a:V,b:V)->V{match(a,b){(V::Z,_)|(_,V::Z)=>V::Z,(V::O,x)|(x,V::O)=>x,(V::C,V::C)=>V::C,_=>V::Q}}
fn xor(a:V,b:V)->V{match(a,b){(V::Q,_)|(_,V::Q)=>V::Q,(V::Z,x)|(x,V::Z)=>x,(V::O,V::O)=>V::Z,_=>V::C}}
fn select(old:V,new:V,g:V)->V{match g{V::Z=>old,V::O=>new,_=>if old==new&&matches!(old,V::Z|V::O){old}else if old==V::Q||new==V::Q{V::Q}else{V::C}}}
fn dims(v:&[Op])->(usize,usize){(v.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|&x|x!=NO).max().unwrap_or(0)as usize+1,v.iter().flat_map(|o|[o.c_condition.0,o.c_target.0]).filter(|&x|x!=NO).max().unwrap_or(0)as usize+1)}
fn hash(v:&[Op])->String{let mut h=Sha3_256::new();for o in v{for x in [o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{h.update(x.to_le_bytes());}}format!("{:x}",h.finalize())}
fn scan(v:&[Op],history:bool)->(serde_json::Value,Vec<Vec<V>>){let(nq,nb)=dims(v);let mut q=vec![V::Z;nq];let mut c=vec![V::Z;nb];for o in v{if o.kind==K::AppendToRegister{if o.q_target.0!=NO{q[o.q_target.0 as usize]=V::Q;}if o.c_target.0!=NO{c[o.c_target.0 as usize]=V::C;}}}let(mut base,mut stack)=(V::O,vec![]);let mut examples=vec![];let mut eligible=0;let mut nonconstant=0;let mut unconditional=0;let mut constant_controls=0;let mut max_quantum=q.iter().filter(|&&x|x==V::Q).count();let mut states=vec![];
for(i,o)in v.iter().enumerate(){if o.kind==K::PushCondition{stack.push(base);base=and(base,c[o.c_condition.0 as usize]);if history{states.push(q.clone());}continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();if history{states.push(q.clone());}continue;}let eff=if o.c_condition.0==NO{base}else{and(base,c[o.c_condition.0 as usize])};let(t,a,b,ct)=(o.q_target.0 as usize,o.q_control1.0 as usize,o.q_control2.0 as usize,o.c_target.0 as usize);
 if matches!(o.kind,K::CCX|K::CCZ)&&eff!=V::Z{let mut controls=vec![a,b];if o.kind==K::CCZ{controls.push(t);}let classic=controls.iter().filter(|&&j|q[j]!=V::Q).count();if classic>0{eligible+=1;if controls.iter().any(|&j|q[j]==V::C){nonconstant+=1;}if controls.iter().any(|&j|matches!(q[j],V::Z|V::O)){constant_controls+=1;}if eff==V::O{unconditional+=1;}if examples.len()<64{examples.push(serde_json::json!({"op":i,"kind":format!("{:?}",o.kind),"control_types":controls.iter().map(|&j|format!("{:?}",q[j])).collect::<Vec<_>>(),"effective_guard_type":format!("{:?}",eff),"classical_control_count":classic}));}}}
 match o.kind{K::X=>q[t]=xor(q[t],eff),K::CX=>q[t]=xor(q[t],and(eff,q[a])),K::CCX=>q[t]=xor(q[t],and(eff,and(q[a],q[b]))),K::R|K::Hmr=>{q[t]=select(q[t],V::Z,eff);if o.kind==K::Hmr{c[ct]=select(c[ct],V::C,eff);}},K::Swap=>{let(x,y)=(q[a],q[t]);q[a]=select(x,y,eff);q[t]=select(y,x,eff);},K::BitInvert=>c[ct]=xor(c[ct],eff),K::BitStore0=>c[ct]=select(c[ct],V::Z,eff),K::BitStore1=>c[ct]=select(c[ct],V::O,eff),K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},_=>unreachable!()}
 max_quantum=max_quantum.max(q.iter().filter(|&&x|x==V::Q).count());if history{states.push(q.clone());}}
assert!(stack.is_empty());(serde_json::json!({"status":"CLASSICAL_CONTROL_TYPE_DIAGNOSTIC_NOT_A_SCORE","input_Q":nq,"input_classical_bits":nb,"static_Toffolis_with_proved_classical_control_and_not_proved_false_guard":eligible,"of_which_nonconstant_classical_control":nonconstant,"of_which_constant_control":constant_controls,"of_which_unconditional_execution_proved":unconditional,"maximum_quantum_dependent_role_count":max_quantum,"examples":examples,"scope":"Conservative source type counts, not executed T or a quantum-width result. No circuit is rewritten."}),states)}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),4);let v=io::load_ops(&a[1]);let h=hash(&v);assert_eq!(h,a[3]);let(mut report,_)=scan(&v,false);report["input_full_sha3_256"]=serde_json::json!(h);report["input_count"]=serde_json::json!(v.len());std::fs::write(&a[2],serde_json::to_string_pretty(&report).unwrap()).unwrap();println!("{}",report);}
#[cfg(test)]mod tests{
 use super::*;use quantum_ecc::{circuit::{QubitId,BitId,RegisterId},sim::Simulator};use sha3::{Shake256,digest::{Update,ExtendableOutput}};
 fn op(k:K,t:u64)->Op{let mut o=Op::empty();o.kind=k;o.q_target=QubitId(t);o}
 fn fixture()->Vec<Op>{let mut qr=op(K::AppendToRegister,0);qr.r_target=RegisterId(0);let mut cr=op(K::AppendToRegister,NO);cr.c_target=BitId(0);cr.r_target=RegisterId(1);let mut x=op(K::X,1);x.c_condition=BitId(0);let mut cc=op(K::CCX,2);cc.q_control1=QubitId(0);cc.q_control2=QubitId(1);let mut phase=op(K::CCZ,2);phase.q_control1=QubitId(0);phase.q_control2=QubitId(1);let mut h=op(K::Hmr,2);h.c_target=BitId(0);let mut swap=op(K::Swap,2);swap.q_control1=QubitId(0);swap.c_condition=BitId(0);vec![qr,cr,x,cc,phase,h,op(K::X,2),swap,op(K::R,2)]}
 fn simulate(v:&[Op],q:u64,c:u64,seed:u64)->Vec<u64>{let mut h=Shake256::default();Update::update(&mut h,&seed.to_le_bytes());let mut r=h.finalize_xof();let mut s=Simulator::new(3,1,&mut r);s.qubits[0]=q;s.bits[0]=c;s.apply_iter(v.iter());s.qubits.clone()}
 #[test]fn classical_tags_are_independent_of_quantum_input_at_every_prefix(){let v=fixture();let(_,states)=scan(&v,true);for c in [0,u64::MAX,0x5555aaaaffff0000]{for seed in 0..4{for i in 0..v.len(){let baseline=simulate(&v[..i+1],0,c,seed);for qi in [u64::MAX,0xaaaa5555ffff0000]{let x=simulate(&v[..i+1],qi,c,seed);for(q,&tag)in states[i].iter().enumerate(){match tag{V::Z=>{assert_eq!(baseline[q],0);assert_eq!(x[q],0);},V::O=>{assert_eq!(baseline[q],u64::MAX);assert_eq!(x[q],u64::MAX);},V::C=>assert_eq!(baseline[q],x[q]),V::Q=>{}}}}}}}}
 #[test]fn quantum_input_is_never_typed_classical_from_basis_simulation(){let v=fixture();let(_,states)=scan(&v,true);assert_eq!(states[0][0],V::Q);assert_eq!(states[3][2],V::Q);assert_eq!(states[5][2],V::Z);}
 #[test]fn abstract_boolean_classical_operations_never_introduce_quantum_dependence(){for a in [V::Z,V::O,V::C]{for b in [V::Z,V::O,V::C]{assert_ne!(and(a,b),V::Q);assert_ne!(xor(a,b),V::Q);for g in [V::Z,V::O,V::C]{assert_ne!(select(a,b,g),V::Q);}}}}
 #[test]fn unknown_guard_cannot_erase_a_quantum_dependency(){assert_eq!(select(V::Q,V::Z,V::C),V::Q);assert_eq!(select(V::Q,V::Z,V::O),V::Z);}
}
